param(
    [Parameter(Mandatory = $true)][string]$Compiler,
    [Parameter(Mandatory = $true)][string]$ScratchDirectory
)
$ErrorActionPreference = 'Stop'
$Compiler = [IO.Path]::GetFullPath($Compiler)
$ScratchDirectory = [IO.Path]::GetFullPath($ScratchDirectory)
[void][IO.Directory]::CreateDirectory($ScratchDirectory)
$source = Join-Path $PSScriptRoot 'aggregate-return-abi.c'
$output = Join-Path $ScratchDirectory 'aggregate-return-abi.exe'
$errorFile = Join-Path $ScratchDirectory 'compile.err'
# Only transport the bytes generated by the custom compiler.
$process = Start-Process -FilePath $Compiler -WindowStyle Hidden -PassThru -RedirectStandardInput $source -RedirectStandardOutput $output -RedirectStandardError $errorFile
[void]$process.Handle
if (!$process.WaitForExit(10000)) {
    $process.Kill()
    throw 'ABI compilation timeout'
}
$process.WaitForExit()
if ($process.ExitCode -ne 0) {
    throw ('ABI compilation failed: ' + [IO.File]::ReadAllText($errorFile))
}
$process = Start-Process -FilePath $output -WindowStyle Hidden -PassThru
[void]$process.Handle
if (!$process.WaitForExit(10000)) {
    $process.Kill()
    throw 'ABI execution timeout'
}
$process.WaitForExit()
if ($process.ExitCode -ne 0) {
    throw "ABI probe returned $($process.ExitCode)"
}
"PASS aggregate return ABI: $([IO.Path]::GetFileName($Compiler))"
"Compiler SHA256: $((Get-FileHash $Compiler).Hash)"
"Source SHA256: $((Get-FileHash $source).Hash)"
